public class ReferenceTest {
    public static void main(String[] args) {
        StringBuilder sb = new StringBuilder("Hello");
        modify(sb);
        System.out.println(sb); // Prints: Hello World
        reassign(sb);
        System.out.println(sb); // Still prints: Hello World
    }

    private static void modify(StringBuilder s) {
        s.append(" World"); // Mutates the object on the heap
    }

    private static void reassign(StringBuilder s) {
        s = new StringBuilder("Goodbye"); // Local copy reassigned, original unaffected
    }
}
